CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('employee','manager','accounting','fleet_admin','super_admin') NOT NULL DEFAULT 'employee',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,make VARCHAR(100) NOT NULL,model VARCHAR(100) NOT NULL,registration VARCHAR(32) NOT NULL UNIQUE,mileage INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('available','service','unsafe') NOT NULL DEFAULT 'available',inspection_due DATE NULL,insurance_due DATE NULL,assigned_user_id BIGINT UNSIGNED NULL,FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE delegations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,destination VARCHAR(190) NOT NULL,purpose TEXT NOT NULL,date_from DATE NOT NULL,date_to DATE NOT NULL,transport VARCHAR(80) NOT NULL,status ENUM('pending','approved','rejected','started','finished') NOT NULL DEFAULT 'pending',manager_id BIGINT UNSIGNED NULL,manager_note TEXT NULL,odo_start INT UNSIGNED NULL,odo_end INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(manager_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80) NULL,entity_id BIGINT UNSIGNED NULL,ip VARCHAR(45) NULL,meta JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
